  if (!src.sessionId || !src.runs.length) { setStatus('当前会话还没有可导出的记录'); return; }
  const text = JSON.stringify(exportEvidence({ sessionId: src.sessionId, title: src.title || (src.other ? '' : state.nav.title), runs: src.runs }), null, 2);
